const items = $input.all();

const seenEmails = new Set();
const output = [];

for (let i = 0; i < items.length; i++) {
  let row = items[i].json;

  // Parse the AI response.
  if (typeof row.text === 'string') {
    const text = row.text
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/, '')
      .trim();

    try {
      row = JSON.parse(text);
    } catch (error) {
      throw new Error(
        `Invalid AI JSON at item ${i + 1}: ${text}`
      );
    }
  }

  // Clean all string values.
  for (const key of Object.keys(row)) {
    if (typeof row[key] === 'string') {
      row[key] = row[key].trim();
    }
  }

  // Standardize email.
  row.Email = String(row.Email ?? '').toLowerCase();

  // Validate email.
  const validEmail =
    /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(row.Email);

  if (!validEmail) continue;

  // Remove duplicate email addresses.
  if (seenEmails.has(row.Email)) continue;
  seenEmails.add(row.Email);

  // Keep only fee-paid students.
  const feePaid = String(row.Fee_Paid ?? '')
    .trim()
    .toLowerCase();

  if (feePaid !== 'yes') continue;

  // Return an n8n item.
  output.push({
    json: row
  });
}

return output;

const items = $input.all();
const review = [];

for (const item of items) {
  const row = { ...item.json };

  for (const key of Object.keys(row)) {
    if (typeof row[key] === 'string') {
      row[key] = row[key].trim();
    }
  }

  const email = String(row.Email ?? '').toLowerCase();

  const validEmail =
    /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);

  if (!validEmail) {
    row.Review_Reason =
      email ? 'Invalid email' : 'Missing email';

    review.push({ json: row });
  }
}

return review;
